'use strict';const $=id=>document.getElementById(id),L=MCLauncher,KEY='mc-gem-launcher-v1',palette=['#f36b78','#79e2a9','#78c9ff','#bd92ff','#ffe097'];let s,aimCol=2,busy=false,sound=false,language='es',soundContext=null,pending=null,drag=null,suppressClick=0,damageTimer;
