const t=k=>texts[language][k],format=n=>n>=1024?n/1024+'K':String(n),nodes=new Map;const sleep=ms=>new Promise(r=>setTimeout(r,reduce()?0:ms));function reduce(){return typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches}
function save(value=s){try{localStorage.setItem(KEY,JSON.stringify(value))}catch{}}function status(str){$('status').textContent=str}
function gemStyle(el,value){const c=L.color(value);el.style.setProperty('--gx',(c%3*50)+'%');el.style.setProperty('--gy',(Math.floor(c/3)*100)+'%');el.style.setProperty('--color',palette[c]);el.querySelector('b').textContent=format(value)}
function drawCols(cols,activeId){const ids=new Set(cols.flat().map(t=>t.id));for(const [id,el]of nodes)if(!ids.has(id)){el.classList.add('vanishing');setTimeout(()=>el.remove(),reduce()?0:200);nodes.delete(id)}cols.forEach((col,c)=>col.forEach((tile,r)=>{let el=nodes.get(tile.id);if(!el){el=document.createElement('div');el.className='gem-tile';el.innerHTML='<span class="gem-art"></span><b></b>';nodes.set(tile.id,el);$('pieces').append(el)}gemStyle(el,tile.value);el.style.left=c*20+'%';el.style.top=r*12.5+'%';el.setAttribute('aria-label',t('value')+' '+tile.value+', '+t('col')+' '+(c+1));if(tile.id===activeId){el.classList.remove('merging');void el.offsetWidth;el.classList.add('merging')}}))}
function drawAim(){const target=L.landing(s,aimCol),row=target?target.row:7;$('aim').style.left=aimCol*20+'%';$('aim').style.setProperty('--landing-top',row*12.5+'%');$('aim').style.setProperty('--aim-top',(row+.5)*12.5+'%');$('aim').classList.toggle('blocked',!target);$('aim').hidden=busy||L.over(s);for(const button of $('columns').children){const c=Number(button.dataset.col);button.classList.toggle('active',c===aimCol);button.classList.toggle('blocked',!L.landing(s,c));button.disabled=busy||!L.landing(s,c)}$('fire').disabled=busy||!target||L.over(s)}
function drawUI(){document.documentElement.lang=language;$('language').value=language;for(const el of document.querySelectorAll('[data-t]'))el.textContent=t(el.dataset.t);$('score').textContent=s.score;$('highest').textContent=format(s.highest);$('chain').textContent=s.bestChain;$('shots').textContent=t('shots')+' · '+s.shots;$('sound').textContent=t(sound?'soundOn':'soundOff');$('fire').textContent=t('fire')+' · '+format(s.current);gemStyle($('currentGem'),s.current);gemStyle($('nextGem'),s.next);$('currentGem').ariaLabel=t('value')+' '+s.current;$('board').ariaLabel=t('board');$('swap').disabled=busy;$('reset').disabled=busy;$('retry').disabled=busy;$('gameover').hidden=!L.over(s);$('columns').innerHTML=Array.from({length:5},(_,i)=>'<button data-col="'+i+'" aria-label="'+t('fire')+' · '+t('col')+' '+(i+1)+'">↑ '+(i+1)+'</button>').join('');$('crew').innerHTML=t('names').map((name,i)=>'<div class="hero '+(s.energy[i]===100?'ready':'')+'" style="--color:'+palette[i]+';--pos:'+(i*25)+'%"><div class="portrait"></div><b>'+name+'</b><div class="charge"><i style="width:'+s.energy[i]+'%"></i></div></div>').join('');drawAim()}
function tone(index,chain){if(!sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!soundContext)soundContext=new Audio();if(soundContext.state==='suspended')soundContext.resume();const ctx=soundContext,o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.setValueAtTime(220+index*65+chain*45,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(500+chain*80,ctx.currentTime+.16);g.gain.setValueAtTime(.04,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);o.start();o.stop(ctx.currentTime+.25)}catch{}}
function effect(step){const c=step.col??aimCol,r=step.row??0,el=document.createElement('div');el.className='burst';el.style.setProperty('--x',(c+.5)*20+'%');el.style.setProperty('--y',(r+.5)*12.5+'%');el.textContent=step.type==='combo'?t('combo')+' ×'+step.chain:'+'+format(step.value);$('effects').append(el);const laser=document.createElement('i');laser.className='laser';laser.style.setProperty('--color',palette[step.color||0]);laser.style.setProperty('--beam-x',(c+.5)*20+'%');laser.style.setProperty('--beam-y',(r+.5)*12.5+'%');laser.style.setProperty('--beam-height',((r+.5)/8*$('board').clientHeight+65)+'px');$('effects').append(laser);setTimeout(()=>{el.remove();laser.remove()},reduce()?0:700);$('reactor').classList.remove('hit');void $('reactor').offsetWidth;$('reactor').classList.add('hit');$('damage').textContent='+'+step.gain;tone(step.color||0,step.chain)}
async function fly(value,col,row){const b=$('board').getBoundingClientRect(),a=$('currentGem').getBoundingClientRect(),p=document.createElement('div');p.className='projectile';p.innerHTML='<span class="gem-art"></span><b></b>';gemStyle(p,value);const width=b.width/5,height=b.height/8,fromX=a.left+a.width/2-b.left-width/2,fromY=a.top+a.height/2-b.top-height/2,toX=col*width,toY=row*height;p.style.left=fromX+'px';p.style.top=fromY+'px';$('effects').append(p);tone(L.color(value),0);if(!reduce()&&p.animate){await p.animate([{left:fromX+'px',top:fromY+'px',opacity:.8},{left:toX+'px',top:toY+'px',opacity:1}],{duration:Math.max(180,Math.min(420,(fromY-toY)*.8)),easing:'cubic-bezier(.2,.5,.6,1)',fill:'forwards'}).finished.catch(()=>{})}p.remove()}
async function fire(col=aimCol){if(busy||L.over(s))return;aimCol=col;const result=L.fire(s,col);if(!result.ok){status(t('blocked'));drawAim();return}clearTimeout(damageTimer);busy=true;pending=result.state;drawUI();status(t('launching'));try{await fly(result.shotValue,col,result.target.row);let added=0;for(const step of result.steps){drawCols(step.cols,step.type==='merge'?step.activeId:null);if(step.type!=='land'){added+=step.gain;effect(step);$('score').textContent=s.score+added;status(step.type==='combo'?t('combo')+' ×'+step.chain:t('merging')+' · '+format(step.value))}await sleep(step.type==='land'?100:260)}}finally{s=result.state;pending=null;busy=false;save();drawCols(s.cols);drawUI();if(L.over(s))status(t('full'));else if(!L.playable(s))status(t('needSwap'));else status(result.chain?t('merged')+result.chain+' · +'+result.damage+t('powerUnit'):t('landed'));damageTimer=setTimeout(()=>{$('damage').textContent=''},1100)}}
function columnAt(x){const rect=$('board').getBoundingClientRect();return Math.max(0,Math.min(4,Math.floor((x-rect.left)/rect.width*5)))}
$('board').addEventListener('pointermove',e=>{if(!busy){aimCol=columnAt(e.clientX);drawAim()}});$('board').addEventListener('click',e=>{if(!busy&&Date.now()>suppressClick){aimCol=columnAt(e.clientX);fire(aimCol)}});$('board').addEventListener('keydown',e=>{if(busy||e.target!==$('board'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();aimCol=Math.max(0,Math.min(4,aimCol+(e.key==='ArrowLeft'?-1:1)));drawAim()}if(e.key==='Enter'||e.key===' '){e.preventDefault();fire(aimCol)}});$('columns').addEventListener('click',e=>{const button=e.target.closest('[data-col]');if(button&&!button.disabled)fire(Number(button.dataset.col))});$('fire').onclick=()=>fire(aimCol);$('swap').onclick=()=>{if(busy)return;s=L.swap(s);save();drawUI();status(t('swapped'))};
$('cannon').addEventListener('pointerdown',e=>{if(busy||e.isPrimary===false||e.button!==undefined&&e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};try{$('cannon').setPointerCapture(e.pointerId)}catch{}});$('cannon').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;aimCol=columnAt(e.clientX);if(Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)>15)drag.moved=true;e.preventDefault();drawAim()});$('cannon').addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const moved=drag.moved;drag=null;const rect=$('board').getBoundingClientRect();if(moved&&e.clientX>=rect.left&&e.clientX<=rect.right){suppressClick=Date.now()+400;fire(columnAt(e.clientX))}});$('cannon').addEventListener('pointercancel',()=>{drag=null});$('cannon').addEventListener('lostpointercapture',()=>{drag=null});
function reset(){if(busy||!confirm(t('confirm')))return;s=L.fresh();aimCol=2;pending=null;save();drawCols(s.cols);drawUI();status(t('first'))}$('reset').onclick=reset;$('retry').onclick=reset;$('sound').onclick=()=>{sound=!sound;if(sound)tone(2,1);drawUI()};$('language').onchange=e=>{language=e.target.value==='en'?'en':'es';try{localStorage.setItem('mc-language',language)}catch{}drawUI();status(s.shots?t('ready'):t('first'))};window.addEventListener('pagehide',()=>save(pending||s));drawCols(s.cols);drawUI();status(L.over(s)?t('full'):s.shots?t('ready'):t('first'));save();
